-- Fotos de puntos de interés (poi-images.js)
-- Cuatro Calas (4/4) y Sierra Espuña (6/13). Wikimedia Commons, licencias CC BY / CC BY-SA / CC0.
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Afloramientos_rocosos_en_la_Cala_La_Carolina.JPG?width=1280', source = 'Inventario Español de Lugares de Interés Geológico (IELIG), IGME — LIG BE006 «Vulcanismo de La Carolina». La coordenada es la del propio punto del inventario; Wikimedia Commons (foto: Mabelcalabuig, CC BY-SA 3.0 es)' WHERE slug = 'vulcanismo-de-la-carolina' AND park_id = (SELECT id FROM parks WHERE slug = 'cuatro-calas');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Antiguo_deposito_de_esparto_en_la_Cala_de_los_Cocederos.JPG?width=1280', source = 'Posición: OpenStreetMap way/1459077450 (ODbL). Uso espartero documentado en Wikimedia Commons («Antiguo deposito de esparto en la Cala de los Cocederos», «Depositos excavados en el acantilado, Cala de los Cocederos»); pendiente de contrastar con fuente documental. El IELIG y Commons escriben «Cocederos»; OpenStreetMap, «Cocedores».; Wikimedia Commons (foto: Mabelcalabuig, CC BY-SA 3.0 es)' WHERE slug = 'playa-de-los-cocedores' AND park_id = (SELECT id FROM parks WHERE slug = 'cuatro-calas');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Cuatro_calas_aguilas_vista_desde_carretera.jpg?width=1280', source = 'Inventario Español de Lugares de Interés Geológico (IELIG), IGME — LIG BE005, cuya denominación oficial es «Playa de Cuatro Calas»; aquí se le da otro nombre para no confundirlo con el del propio espacio protegido. approx: el punto del inventario representa el conjunto del tramo costero, no un afloramiento puntual; Wikimedia Commons (foto: Edumartinez89, CC BY-SA 3.0 es)' WHERE slug = 'conglomerados-de-cuatro-calas' AND park_id = (SELECT id FROM parks WHERE slug = 'cuatro-calas');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Calarreona%2C_afloramientos_rocosos.Las_Cuatro_Calas.JPG?width=1280', source = 'Posición: OpenStreetMap (ODbL). Sendero SL-MU 18 homologado por la FMRM. Su recorrido no aparece dibujado en el mapa: el sendero está señalizado sobre el terreno, pero no cartografiado en OpenStreetMap, que es de donde sale la capa de senderos; Wikimedia Commons (foto: Mabelcalabuig, CC BY-SA 3.0 es)' WHERE slug = 'playa-de-calarreona' AND park_id = (SELECT id FROM parks WHERE slug = 'cuatro-calas');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Pozos_de_la_Nieve_de_Murcia_11-03-2024.jpg?width=1280', source = 'Bien de Interés Cultural, categoría Sitio de Interés Etnográfico (Dirección General de Bienes Culturales, Región de Murcia). Posición de los 28 pozos en OpenStreetMap (man_made=ice_house, ODbL). approx: la coordenada es la del Pozo 1 (node/8543844778) y representa el conjunto; Wikimedia Commons (foto: Lorenzo Soriano, CC BY 4.0)' WHERE slug = 'pozos-de-la-nieve' AND park_id = (SELECT id FROM parks WHERE slug = 'sierra-espuna');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Casa_Forestal_de_Huerta_Espu%C3%B1a._Sierra_Espu%C3%B1a.jpg?width=1280', source = 'OpenStreetMap way/900533315 (historic=yes, ODbL). Pendiente de contrastar con fuente documental; Wikimedia Commons (foto: Lorenzo Soriano, CC BY-SA 4.0)' WHERE slug = 'casa-forestal-de-huerta-espuna' AND park_id = (SELECT id FROM parks WHERE slug = 'sierra-espuna');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Centro_de_Visitantes_y_Gesti%C3%B3n_Ricardo_Codorniu._Sierra_Espu%C3%B1a.jpg?width=1280', source = 'OpenStreetMap way/170061146 (amenity=ranger_station, tourism=information, historic=house, ODbL); Wikimedia Commons (foto: Lorenzo Soriano, CC BY-SA 4.0)' WHERE slug = 'centro-de-visitantes-ricardo-codorniu' AND park_id = (SELECT id FROM parks WHERE slug = 'sierra-espuna');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Antiguo_Sanatorio_de_Tuberculosos_de_Sierra_Espu%C3%B1a_03.jpg?width=1280', source = 'OpenStreetMap way/132482920 (historic=building, building=hospital, ruins=yes, ODbL); denominación confirmada en Nominatim. Fechas de construcción y cierre pendientes de contrastar con fuente documental; Wikimedia Commons (foto: Jayma photography ltd, CC BY-SA 4.0)' WHERE slug = 'sanatorio-de-tuberculosos' AND park_id = (SELECT id FROM parks WHERE slug = 'sierra-espuna');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Restos_de_la_Torre_del_Azaraque_(Alhama_de_Murcia).jpg?width=1280', source = 'OpenStreetMap way/1097841454 (historic=ruins, man_made=tower, ODbL). Época y función pendientes de contrastar con fuente documental; Wikimedia Commons (foto: Lorenzo Soriano, CC BY-SA 4.0)' WHERE slug = 'torre-del-azaraque' AND park_id = (SELECT id FROM parks WHERE slug = 'sierra-espuna');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Iglesia_de_Santa_Eulalia_de_Merida_(1).jpg?width=1280', source = 'Decreto 96/2002, de 7 de junio, del Consejo de Gobierno de la Región de Murcia, por el que se declara bien de interés cultural, con categoría de monumento, la iglesia de Santa Eulalia de Mérida, en Totana. Posición: OpenStreetMap way/152263929 (ODbL); Wikimedia Commons (foto: Pedro J Pacheco, CC BY-SA 3.0 es)' WHERE slug = 'santuario-de-santa-eulalia' AND park_id = (SELECT id FROM parks WHERE slug = 'sierra-espuna');
